using System;using System.IO;using System.Linq;using System.Collections.Generic;using Frociart;
public static class ForLoopTests {
 static int checks;static string root;
 static void Eq(object a,object b,string label){checks++;if(!Object.Equals(a,b))throw new Exception(label+": expected "+a+" actual "+b);}
 static Interpreter Run(Diagram d,string inputs){var r=new Interpreter(d);var values=inputs.Split('|');int used=0;for(int t=0;t<11000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;t++){if(r.State==RuntimeState.WaitingForInput){Eq(false,r.Step(),"wait is stable");Eq(true,r.ProvideInput(values[used++]),"input");}else if(r.State==RuntimeState.WaitingForFile){Eq(false,r.Step(),"file wait stable");string data=values[used++];Eq(true,data.StartsWith("F:"),"file fixture");Eq(true,r.ProvideFile(r.PendingFile,data.Substring(2)),"file accepted");}else r.Step();}Eq(inputs.Length==0?0:values.Length,used,"input requests exactly once");return r;}
 static void Valid(Diagram d,string inputs,string expected,string name){var r=Run(d,inputs);Eq(RuntimeState.Completed,r.State,name+" completes "+r.Error);Eq(expected,String.Join("|",r.Output),name+" output");}
 static void Mutant(Action<Diagram> edit,string expected){var d=FlowPseudocode.Decode("p=2\nPER i DA 1 A 5 PASSO p FAI\nSTAMPA i\nFINE PER");edit(d);string code=FlowPseudocode.Encode(d);Eq(false,code.Contains("PER i DA"),"edited pattern not hidden");var original=Run(d,"");var back=Run(FlowPseudocode.Decode(code),"");Eq(original.State,back.State,"edited state");Eq(String.Join("|",original.Output),String.Join("|",back.Output),"edited behavior");if(expected!=null)Eq(expected,String.Join("|",back.Output),"edited oracle");}
 static void Fuzz(){var random=new Random(8723);for(int trial=0;trial<160;trial++){var d=FlowPseudocode.Decode("p=2\nPER i DA 1 A 5 PASSO p FAI\nSE i=3 ALLORA\nSTAMPA i*2\nALTRIMENTI\nSTAMPA i\nFINE SE\nFINE PER\nSTAMPA \"fine\"");int kind=trial%4;if(kind==0){var edge=d.Edges[random.Next(d.Edges.Count)];edge.To=d.Nodes[1+random.Next(d.Nodes.Count-1)].Id;}else if(kind==1){d.Edges.RemoveAt(random.Next(d.Edges.Count));}else if(kind==2){var body=d.Nodes.First(n=>n.Kind==NodeKind.Output);body.Text=random.Next(2)==0?"limite_ciclo_1":"passo_ciclo_1";}else{var init=d.Nodes.Single(n=>n.Kind==NodeKind.Process&&n.Text.Contains(" = int("));init.Text+="; z=3";}var before=DiagramIO.EncodeDocument(d);string code=FlowPseudocode.Encode(d);var back=FlowPseudocode.Decode(code);var a=Run(d,"");var b=Run(back,"");Eq(a.State,b.State,"mutated graph state "+trial);Eq(String.Join("|",a.Output),String.Join("|",b.Output),"mutated graph output "+trial);Eq(d.Nodes.Count,back.Nodes.Count,"mutated graph node count "+trial);Eq(d.Edges.Count,back.Edges.Count,"mutated graph edges "+trial);Eq(true,before.SequenceEqual(DiagramIO.EncodeDocument(d)),"mutated export nonmutating "+trial);}}
 public static int Main(){try{root=Environment.GetEnvironmentVariable("FOR_QA");Directory.CreateDirectory(Path.Combine(root,"pc-docs"));foreach(var file in Directory.GetFiles(Path.Combine(root,"fixtures"),"*.pseudo").OrderBy(f=>f)){string name=Path.GetFileNameWithoutExtension(file),expected=File.ReadAllText(Path.ChangeExtension(file,"expected")),input=File.ReadAllText(Path.ChangeExtension(file,"inputs"));var d=FlowPseudocode.Decode(File.ReadAllText(file));var before=DiagramIO.EncodeDocument(d);string code=FlowPseudocode.Encode(d);Eq(true,code.Contains("PER i DA"),name+" readable FOR");Eq(true,before.SequenceEqual(DiagramIO.EncodeDocument(d)),name+" export nonmutating");Valid(d,input,expected,name);Valid(FlowPseudocode.Decode(code),input,expected,name+" text roundtrip");Valid(DiagramIO.Clone(d),input,expected,name+" project roundtrip");File.WriteAllBytes(Path.Combine(root,"pc-docs",name+".frociart"),before);File.WriteAllText(Path.Combine(root,"pc-docs",name+".txt"),code);string other=Path.Combine(root,"java-docs",name+".frociart");if(File.Exists(other)){Valid(DiagramIO.Load(other),input,expected,name+" Android file");Eq(code,File.ReadAllText(Path.ChangeExtension(other,"txt")),name+" platform text");}}
 foreach(string value in new[]{"0","1.5","2147483648","-2147483649","vero","\"2\"","[2]"}){var r=Run(FlowPseudocode.Decode("p="+value+"\ni=91\nPER i DA 1 A 3 PASSO p FAI\nSTAMPA i\nFINE PER"),"");Eq(RuntimeState.Error,r.State,"invalid dynamic step "+value);Eq(0,r.Output.Count,"no invalid iteration");Eq("91",ValueFormatter.Format(r.Variables["i"]),"failed init atomic");Eq(true,r.Error.Contains("passo")||r.Error.Contains("PASSO"),"step-specific error");}
 foreach(string value in new[]{"0","1.5","2147483648"}){bool failed=false;try{FlowPseudocode.Decode("PER i DA 1 A 3 PASSO "+value+" FAI\nFINE PER");}catch(ArgumentException){failed=true;}Eq(true,failed,"invalid constant rejected");}
 Mutant(d=>d.Nodes.Single(n=>n.Kind==NodeKind.Decision).Text="i < limite_ciclo_1","1|3");
 Mutant(d=>d.Nodes.Single(n=>n.Kind==NodeKind.Process&&n.Text.StartsWith("i = i +")).Text="i = i + 1","1|2|3|4|5");
 Mutant(d=>d.Nodes.Single(n=>n.Kind==NodeKind.Output).Text="limite_ciclo_1","5|5|5");
 Mutant(d=>d.Nodes.Single(n=>n.Kind==NodeKind.Process&&n.Text.Contains(" = int(")).Text += "; altra = 7","1|3|5");
 Eq(2.0,ExpressionLanguage.Evaluate("int(p, \"passo\")",new Dictionary<string,object>{{"p",2}}),"host numeric values");
 Fuzz();
 Console.WriteLine("FOR_LOOP PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
